def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    h, w = g.shape
    for x in range(w):
        cur = None
        changed = False
        for y in range(h):
            if g[y, x] != bg:
                cur = g[y, x]
            elif cur is not None:
                g[y, x] = cur
                changed = True
        if changed:
            emit(g, f"Column {x}: the coloured cell drips its colour down to the bottom edge, filling the empty cells below it.")
    emit(g, "Every coloured cell has been extended downward to the bottom; this is the final grid.")
    return g
